INSERT INTO safety_rules VALUES ('rule-fungal-acne', 'Fungal Acne (Malassezia)', 'fungal-acne', 'Screens for lipids, fatty acids, polysorbates, and esters that feed Malassezia yeast and trigger fungal acne / pityrosporum folliculitis.', '["polysorbate 20","polysorbate 60","polysorbate 80","isopropyl myristate","isopropyl palmitate","myristic acid","palmitic acid","oleic acid","lauric acid","stearic acid","coconut oil","sweet almond oil","sunflower seed oil","shea butter","peg-100 stearate"]');
INSERT INTO safety_rules VALUES ('rule-pregnancy', 'Pregnancy & Lactation', 'pregnancy', 'Checks for high-risk obstetric ingredients including retinoids, high-dose salicylic acid, hydroquinone, and chemical sunscreens contraindicated during pregnancy.', '["retinol","salicylic acid","hydroquinone","avobenzone","homosalate","octisalate","octocrylene"]');
INSERT INTO safety_rules VALUES ('rule-non-comedogenic', 'Non-Comedogenic (Pore-Clogging)', 'non-comedogenic', 'Identifies ingredients with high comedogenic ratings (4-5) that trap sebum and block pores leading to blackheads and inflammatory acne breakouts.', '["coconut oil","isopropyl myristate","isopropyl palmitate","myristic acid","carraceenan","algae extract","lauric acid","sodium lauryl sulfate (sls)"]');
INSERT INTO safety_rules VALUES ('rule-silicone-free', 'Silicone-Free', 'silicone-free', 'Verifies the absence of occlusive silicones that form a barrier layer over the skin surface.', '["dimethicone","cyclomethicone","cyclopentasiloxane","amodimethicone","dimethiconol","phenyl trimethicone"]');
INSERT INTO safety_rules VALUES ('rule-fragrance-free', 'Fragrance & Essential Oil-Free', 'fragrance-free', 'Ensures the product contains zero synthetic perfumes or volatile essential plant oils known to cause contact dermatitis.', '["fragrance (parfum)","limonene","linalool","citronellol","citral","eugenol","geraniol","lavender oil","tea tree leaf oil"]');
INSERT INTO safety_rules VALUES ('rule-paraben-free', 'Paraben-Free', 'paraben-free', 'Screens for synthetic alkyl ester preservatives associated with endocrine disrupting potential.', '["methylparaben","propylparaben","ethylparaben","butylparaben","isobutylparaben"]');
INSERT INTO safety_rules VALUES ('rule-sulfate-free', 'Sulfate-Free', 'sulfate-free', 'Verifies freedom from harsh cleansing surfactants that strip skin natural lipid moisture barriers.', '["sodium lauryl sulfate (sls)","sodium laureth sulfate (sles)","ammonium lauryl sulfate"]');
INSERT INTO safety_rules VALUES ('rule-alcohol-free', 'Drying Alcohol-Free', 'alcohol-free', 'Ensures absence of simple drying denatured alcohols that induce transepidermal water loss and skin redness.', '["alcohol denat","sd alcohol","isopropyl alcohol","ethanol","ethyl alcohol"]');
INSERT INTO safety_rules VALUES ('rule-vegan-cruelty', 'Vegan & Cruelty-Free', 'vegan-cruelty-free', 'Verifies the product excludes animal-derived byproducts such as snail mucin, beeswax, lanolin, carmine, and gelatin.', '["snail mucin","beeswax","lanolin","carmine","gelatin","collagen"]');
INSERT INTO safety_rules VALUES ('rule-reef-safe', 'Reef-Safe Sunscreen', 'reef-safe', 'Screens solar products for chemical UV filters linked to coral reef bleaching and marine toxicity in ocean ecosystems.', '["oxybenzone","octinoxate","ethylhexyl methoxycinnamate","octocrylene","avobenzone"]');
INSERT INTO safety_rules VALUES ('rule-rosacea-eczema', 'Rosacea & Eczema-Trigger Free', 'rosacea-eczema', 'Filters out physical and chemical skin irritants that precipitate erythema flares, stinging, and compromised skin barrier symptoms.', '["glycolic acid","lactic acid","salicylic acid","retinol","fragrance (parfum)","alcohol denat","sodium lauryl sulfate (sls)","lavender oil"]');
INSERT INTO safety_rules VALUES ('rule-malassezia-free', 'Malassezia Yeast Free', 'malassezia-free', 'Rigorous medical verification against lipid sources that harbor Malassezia furfur and seborrheic dermatitis triggers.', '["polysorbate 20","polysorbate 60","polysorbate 80","stearic acid","palmitic acid","myristic acid","coconut oil","shea butter"]');
INSERT INTO safety_rules VALUES ('rule-nut-allergy', 'Nut-Allergy Safe', 'nut-allergy-safe', 'Screens for botanical oils and extracts derived from tree nuts that pose severe contact allergen risks.', '["sweet almond oil","macadamia nut oil","walnut shell powder","argan oil","hazelnut oil"]');
INSERT INTO safety_rules VALUES ('rule-gluten-free', 'Gluten-Free', 'gluten-free', 'Checks for grain-derived proteins and extracts containing gluten proteins for individuals with celiac disease or gluten sensitivity.', '["hydrolyzed wheat protein","barley extract","rye seed extract","wheat germ oil"]');
INSERT INTO safety_rules VALUES ('rule-phthalate-free', 'Phthalate-Free', 'phthalate-free', 'Ensures product is formulated without plasticizing chemical fixatives associated with hormone disruption.', '["dibutyl phthalate","diethyl phthalate","dimethyl phthalate","fragrance (parfum)"]');
